#!/usr/bin/env python3
"""Generate reproducible cost coverage; never substitute assumptions for quotes."""
import csv, json
from pathlib import Path
from html import escape as e
R=Path(__file__).resolve().parent.parent
BOC='https://www.boc.cn/ebanking/service/cs1/200905/t20090506_990712.html'
SAFE='https://www.safe.gov.cn/tianjin/2024/0621/2529.html'
IRS='https://www.irs.gov/individuals/international-taxpayers/foreign-currency-and-currency-exchange-rates'
channels=list(csv.DictReader((R/'data/channels.csv').open()))
rows=[]
for c in channels:
 for amount in range(10000,400001,10000):
  rows.append(dict(channel_id=c['id'],amount_usd=amount,total_cost_usd='',fx_cost_usd='',tax_usd='',bank_fee_usd='',status='UNVERIFIED — no case-specific quote; not zero',source_url=c['source_url']))
with (R/'data/cost-grid.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def link(url,label='Official source'):return f'<a href="{e(url)}">{e(label)}</a>'
def page(title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · China3</title><link rel="stylesheet" href="style.css"><style>main{{max-width:1100px;margin:auto;padding:20px}}.notice{{border-left:4px solid #b45309;padding:16px;background:#fff7ed;color:#422006}}summary{{cursor:pointer;padding:15px;font-weight:bold}}.scroll{{overflow-x:auto}}td,th{{padding:10px;text-align:left}}td:empty::after{{content:' ';display:inline-block}}table{{width:100%;border-collapse:collapse}}tr{{border-bottom:1px solid #ddd}}nav{{display:flex;flex-wrap:wrap;gap:16px}}small{{display:block}}@media(max-width:600px){{main{{padding:12px}}td,th{{padding:8px;font-size:14px}}}}</style></head><body><main><nav><a href="index.html">Home</a><a href="costs.html">Cost comparison</a><a href="deep-channels.html">35 channels & pros/cons</a><a href="cost-review.html">Flagged for Review</a><a href="deep-us-tax.html">Tax & reporting</a></nav><h1>{title}</h1>{body}<footer><p>Research update: 9 November 2026. Educational research, not an execution service or individualized legal/tax advice.</p></footer></main></body></html>'''
body=f'''<p class="notice"><strong>Bottom line: a cheapest all-in route cannot be established from the available facts.</strong> Blank cells mean unverified, never free. No bank quote, source-of-funds history, tax basis or account eligibility was supplied. All 40 increments are included without requiring input.</p>
<h2>Executive decision brief</h2><ol><li><strong>Prioritize a documented bank transfer if the money is lawful current-account income.</strong> SAFE permits overseas individuals to buy FX with identification and transaction-valued source materials including tax documents. Foreign permanent-resident ID holders have a convenience-quota provision. US citizenship alone does not establish the account's classification. {link(SAFE,'SAFE: exact eligibility text')}</li><li><strong>Identify the money before choosing the channel.</strong> Earnings, property proceeds, inheritance, company money and previously imported savings are not interchangeable legal categories. The existing <a href="deep-channels.html">channel register</a> explains conditional routes and their pros/cons; none is automatically available.</li><li><strong>Separate charges from taxes.</strong> A remittance tariff is not an income tax or statutory penalty. Tax documents can substantiate prior tax compliance; this source does not establish a universal tax on the transferred balance. Do not treat an unexplained bank deduction as tax. {link(SAFE)}</li><li><strong>Do not assume conversion has no US tax consequences.</strong> US tax determinations normally use USD and the relevant exchange rate. Actual tax needs transaction history and applicable tax rules; no universal percentage is quoted here. {link(IRS,'IRS guidance')} · <a href="deep-us-tax.html">Detailed tax research and reporting duties</a></li></ol>
<h2>What can actually be calculated?</h2><p>BOC's public electronic-banking table states a cross-border wire charge of 1‰, minimum CNY 50, maximum CNY 260, plus CNY 150 for destinations outside Hong Kong/Macao/Taiwan. It also expressly allows agreements, promotions and local differences. This is a published baseline, <strong>not a confirmed 2026 customer quote</strong>. {link(BOC)}</p>
<p>For one eligible BOC wire to the US: <code>F(A,r) = min(max(0.001 × A × r, 50), 260) + 150</code> CNY. Here A is USD wire principal before deductions, and r is the bank's applicable CNY-per-USD fee valuation rate. Neither r nor the FX execution rate is assumed. The arithmetic tariff component is CNY 200–410 per wire, excluding all other costs; this is not a bound on total cost. Multiple lawful installments incur their own fees. Do not split transactions to evade controls.</p>
<p>USD equivalent of this component is F(A,r)/r if that same rate is applicable. Total economic cost additionally needs actual FX spread, intermediary/recipient charges, applicable taxes and professional fees. No numeric all-in USD estimate can be supported without those inputs. The source supports the tariff only—not eligibility, conversion pricing, or total cost.</p>
<h2>All 40 increments · one-wire BOC tariff component</h2><p>No USD/CNY rate invented. These are <strong>derived formulas</strong>, not bank quotes. USD amount means wire principal, not guaranteed net proceeds.</p><div class="scroll"><table><thead><tr><th>USD principal</th><th>Published component (CNY)</th><th>All-in cost USD<br>UNVERIFIED</th><th>Source</th></tr></thead><tbody>'''
for a in range(10000,400001,10000):
 body+=f'<tr><td>${a:,}</td><td>min(max({a//1000} × r, 50), 260) + 150</td><td></td><td>{link(BOC,"BOC tariff")}</td></tr>'
body+='</tbody></table></div><h2>Every method × every increment</h2><p>All 1,400 combinations are explicitly covered below and in the <a href="data/cost-grid.csv">downloadable CSV</a>. Each channel link is an inherited legal/context source, <strong>not evidence of a fee quote</strong>. Underlying channel claims were not all re-fetched this session. Prohibited or unsuitable channels are included for completeness, not recommendations. Numeric costs stay blank.</p>'
for c in channels:
 body+=f'<details id="{c["id"]}"><summary>{c["id"]} · {e(c["channel"])} · {e(c["group"])}</summary><p>Eligibility: {e(c["who"])}. {e(c["limit_or_condition"])}</p><p>Pros: {e(c["pros"])}<br>Cons: {e(c["cons"])}</p><p>{link(c["source_url"],"Official channel context (prior-session research)")}</p>'
 if c['group'].startswith('PROHIBITED'):
  body+='<p><strong>Do not execute.</strong> No evasion instructions or estimated savings are provided. Use a licensed-bank route appropriate to the real funds.</p>'
 else:
  body+='<p><strong>Operational checklist (analysis, not a bank procedure guarantee):</strong></p><ol><li>Confirm this channel’s stated eligibility and actual ownership/source of funds against the linked rule.</li><li>Have the licensed bank identify the applicable current document list and any approval or registration requirement; do not misstate purpose.</li><li>Provide the authentic identity, source/transaction and applicable tax records for bank review. Approval is not assumed.</li><li>Only after approval, obtain a written rate and itemized sending/intermediary/receiving fee quote; compare the resulting net USD.</li><li>If this channel actually permits outward transfer, instruct the approved transaction to the verified beneficiary, retain receipts and reconcile the received amount; complete applicable reporting. Closed-loop investments, spending, and inward-only channels do not turn into unrestricted USD withdrawals.</li></ol>'
 body+='<div class="scroll"><table><thead><tr><th>USD principal</th><th>Total USD cost<br>UNVERIFIED</th><th>Status / source</th></tr></thead><tbody>'
 for a in range(10000,400001,10000):body+=f'<tr><td>${a:,}</td><td></td><td>No verified quote · {link(c["source_url"])}</td></tr>'
 body+='</tbody></table></div></details>'
body+='<p><a href="cost-review.html">Read verification limitations and irregularities before relying on this page.</a></p>'
(R/'costs.html').write_text(page('CNY → USD · cost comparison',body))
flags=[('COST-01','All-in cost cannot be verified','FX spread, intermediary and receiving fees, source taxes, US tax basis, account identity and transaction eligibility are unknown. All numeric total-cost cells remain blank.',BOC),('COST-02','Old baseline is not a current quote','The retrieved BOC table describes rates effective 2014-11-01 and local/contract/promotional exceptions. Its linked promotions are not assumed current. Formula rows are conditional arithmetic only.',BOC),('COST-03','Inherited research is not newly verified','35 channel entries and 84 source-register entries already existed. A source-domain allowlist and a working link do not prove legal accuracy, currentness or that a linked provision supports each sentence. Prior verification labels are historical, not this session’s attestation. Review the inherited tables before acting.',SAFE),('COST-04','No universal tax percentage established','No supplied money-origin history, acquisition dates, tax returns, basis or filing status. No zero-tax promise and no penalty estimate can be made from the account balance alone.',IRS),('COST-05','Bank product URL returned a soft 404','An exploratory BOC English product URL redirected to “page does not exist”. It was rejected as substantive evidence. A success HTTP/tool status alone is insufficient. The tariff URL below was actually read.',BOC),('COST-06','Exact steps remain bank- and case-dependent','Checklists are analysis rather than bank-certified execution instructions. No false certainty about documents, timing, permanent-resident classification, approval or channel availability is offered.',SAFE)]
(R/'data/cost-flags.json').write_text(json.dumps(flags,ensure_ascii=False,indent=2)+'\n')
review='<p class="notice">Unverified items do not block publication, but they do block a claim that a specific route is cheapest or a numeric total is confirmed. This page supplements <a href="deep-review.html">all prior flagged findings</a>.</p><table><thead><tr><th>Flag</th><th>Finding / action</th><th>Official reference</th></tr></thead><tbody>'
for id,title,text,url in flags:review+=f'<tr><td>{id}</td><td><strong>{e(title)}</strong><p>{e(text)}</p></td><td>{link(url)}</td></tr>'
review+='</tbody></table><h2>Verification performed this session</h2><p>Read substantive full text of SAFE Tianjin 2024 case (9), SAFE Ningxia 2022 Q&amp;A (8), the BOC electronic-banking tariff and IRS currency guidance on 9 November 2026. Publication 525 retrieval returned only its first chunk, not the foreign-currency section; no new section-specific tax assertion was certified from it. All other source verifications are inherited records, not fresh verification.</p><p>Tests check coverage, blank numeric unknowns, reproducible generation and local links. These tests do not verify the law or live external pages.</p>'
(R/'cost-review.html').write_text(page('Flagged for Review · costs & audit',review))
print(f'Generated 40 tariff formulas and {len(rows)} method/amount rows; unknown costs deliberately blank.')
